"use client";
import { useRef } from "react";
import {
  TypeGlyphs,
  typeInteractive,
  typeUnits,
  useTypeMotion,
  type TypographyMotionProps,
} from "./typography-shared";
import { typeStaggerProgress } from "./typography-math";
export interface PoppingTextProps extends TypographyMotionProps {
  rotation?: number;
  stagger?: number;
  overshoot?: number;
}
export function PoppingText({
  text = "BUILT FOR SPEED",
  rotation = 18,
  stagger = 0.5,
  overshoot = 1.7,
  ...props
}: PoppingTextProps) {
  const root = useRef<HTMLSpanElement>(null);
  useTypeMotion(
    root,
    props,
    (p) => {
      const units = typeUnits(root.current!);
      units.forEach((unit, i) => {
        const q = typeStaggerProgress(p, i, units.length, stagger);
        const scale = 1 + (overshoot + 1) * Math.pow(q - 1, 3) + overshoot * Math.pow(q - 1, 2);
        unit.style.transform = `scale(${Math.max(0, scale)}) rotate(${Math.sin(i * 2.4) * rotation * (1 - q)}deg)`;
        unit.style.opacity = String(Math.min(1, q * 5));
      });
    },
    `${text}:${rotation}:${stagger}:${overshoot}`,
  );
  return (
    <span
      ref={root}
      className={props.className}
      style={{ display: "inline-block", ...props.style }}
      aria-label={text}
      data-typography="popping-text"
      {...typeInteractive(props.trigger)}
    >
      <span aria-hidden="true">
        <TypeGlyphs text={text} />
      </span>
    </span>
  );
}
